import { useState } from "react";
import "./css/Festval_card_item.css";

const Festval_card_item = () => {

    
  const [data, setData] = useState(null);
  
  const Loging = async() => {
    const baseUrl = "http://apis.data.go.kr/B551011/KorService1/searchFestival1";
    const serviceKey = "Av0j4qFKXlogzFTNST8uPV8AmR6bdc5h9gNecQv1RR7v92yhfpCYFHj19OoN6mlq00fxLxYyEif4u5cu2GP%2BQA%3D%3D";
    const MobileOS = "ETC";
    const MobileApp = "Nado";
    const eventStartDate = "20241101";
    const type = "json";
    try{
      const response = await axios.get(baseUrl+"?serviceKey="+serviceKey+"&MobileOS="+MobileOS+"&MobileApp="+MobileApp+"&arrange=A&listYN=Y&eventStartDate=20241101&_type="+type);
        setData(response.data); 
        console.log(response.data);
        console.log(JSON.stringify(data));
    }catch(e){
      alert();
      console.log(e);
    }
  };

  Loging();



    return(
        <div className='card_list_item'>            
            <img className='media_header' src={"/image/common.jpeg"} alt="com" />
            <div className="media_item">              
              <ul className="media_info">
                <li className="media_alram">
                    <span>준비중</span>
                </li>              
                <li className="media_title">
                    축제 명
                </li>                
                <li className="media_date">
                  <span className="sub">기간</span>                  
                  <span>시작일</span>~<span>종료일</span>                  
                </li>
                <li className="media_address">
                  <span className="sub">장소</span>                  
                  <span>축제 주소</span>                  
                </li>
                <li className="media_link">
                  <a className="media_map" href="#">지도보기</a>
                  <a className="media_home" href="#">홈페이지</a>
                </li>
              </ul>              
            </div>
        </div>
    );
};

export default Festval_card_item;
